  (1, 'East Los Angeles College', '02430', 39063389278, '{"blocks":[{"courses":[{"alternatives":[],"catalog_addition":false,"code":"ARC 201","units":3,"units_max":null},{"alternatives":[],"catalog_addition":true,"code":"ARC 202","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"ARC 261","units":3,"units_max":null}],"minimum":null,"name":"Certificate of Achievement in Architectural Design: Complete the following additional courses","option_group":null,"rule":"all","stated":{"max":9,"min":9}},{"courses":[{"alternatives":[],"catalog_addition":false,"code":"ARC 132","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"ARC 133","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"ARC 161","units":2,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"ARC 164","units":2,"units_max":null},{"alternatives":[],"catalog_addition":true,"code":"ARC 172","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"ARC 223","units":1,"units_max":null},{"alternatives":[{"catalog_addition":true,"code":"ARC 221","units":2}],"catalog_addition":true,"code":"ARC 262","units":3,"units_max":null},{"alternatives":[{"catalog_addition":true,"code":"MATH 241S","units":4},{"catalog_addition":true,"code":"MATH 260","units":5},{"catalog_addition":true,"code":"MATH 260S","units":5}],"catalog_addition":true,"code":"MATH 241","units":4,"units_max":null}],"minimum":null,"name":"Complete the following additional courses","option_group":null,"rule":"all","stated":{"max":21,"min":20}}],"program":{"careers":["architectural office","environmental design","related design-focused industry"],"degree_elective_units":{"max":null,"min":null},"degree_total":{"max":61,"min":60},"electives_fill_degree":true,"ge_pattern":"LACCD General Education Plan","ge_units":{"max":27,"min":27},"measure":"units","open_elective_units":null,"outcomes":["Analyze and discuss effectively the impact of theoretical, social, political, economic and cultural concepts that affect our built environment.","Appraise and compare traditional architectural techniques along with CAD (Computer-Aided Design) design process.","Create complex professional multi-media presentations as a means to communicate design intent."],"section_heading":"Architectural Design, Associate in Arts Degree (Academic Plan E002430C)","total_units":{"max":null,"min":null}}}'::jsonb, '{"arithmetic":"incomplete","coverage":true,"invented":true,"listed":12,"placed":7}'::jsonb, '{"arithmetic":"incomplete","confidence":{"catalog_year":100,"course_list_match":58,"ge_pattern":100,"source":80,"unit_arithmetic":30},"coverage":true,"gaps":["nested_award_not_read"],"invented":true,"listed":12,"placed":7}'::jsonb),
  (2, 'East Los Angeles College', '08252', 39063389278, '{"blocks":[{"courses":[{"alternatives":[],"catalog_addition":false,"code":"ARC 165","units":2,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"ARC 210","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"ARC 211","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"ARC 223","units":1,"units_max":null}],"minimum":null,"name":"COMPLETE THE FOLLOWING ADDITIONAL COURSES","option_group":null,"rule":"all","stated":{"max":12,"min":12}},{"courses":[{"alternatives":[{"catalog_addition":true,"code":"ARC 272","units":3}],"catalog_addition":true,"code":"ARC 271","units":3,"units_max":null}],"minimum":null,"name":"LIST A: COMPLETE THE COURSE BELOW NOT COMPLETED AS PART OF THE ARCHITECTURAL TECHNOLOGY CERTIFICATE OF ACHIEVEMENT","option_group":null,"rule":"all","stated":{"max":null,"min":null}}],"program":{"careers":["construction management"],"degree_elective_units":{"max":null,"min":null},"degree_total":{"max":61,"min":61},"electives_fill_degree":true,"ge_pattern":"LACCD General Education Plan","ge_units":{"max":27,"min":27},"measure":"units","open_elective_units":null,"outcomes":["Appraise and compare traditional architectural techniques along with CAD (Computer Aided Design) design process.","Create complex professional multi-media presentations as a means to communicate design intent."],"section_heading":"(Academic Plan E008252C)","total_units":{"max":null,"min":null}}}'::jsonb, '{"arithmetic":"incomplete","coverage":true,"invented":true,"listed":10,"placed":4}'::jsonb, '{"arithmetic":"incomplete","confidence":{"catalog_year":100,"course_list_match":40,"ge_pattern":100,"source":80,"unit_arithmetic":30},"coverage":true,"gaps":["nested_award_not_read"],"invented":true,"listed":10,"placed":4}'::jsonb),
  (3, 'East Los Angeles College', '21157', 39063389278, '{"blocks":[{"courses":[],"minimum":null,"name":"Skills Certificate in Architectural Technology","option_group":null,"rule":"all","stated":{"max":14,"min":14}},{"courses":[{"alternatives":[],"catalog_addition":false,"code":"ARC 115","units":2,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"ARC 151","units":3,"units_max":null},{"alternatives":[{"catalog_addition":true,"code":"ARC 272","units":3}],"catalog_addition":true,"code":"ARC 271","units":3,"units_max":null}],"minimum":null,"name":"COMPLETE THE FOLLOWING ADDITIONAL COURSES","option_group":null,"rule":"all","stated":{"max":8,"min":8}}],"program":{"careers":[],"degree_elective_units":{"max":null,"min":null},"degree_total":{"max":null,"min":null},"electives_fill_degree":false,"ge_pattern":null,"ge_units":{"max":null,"min":null},"measure":"units","open_elective_units":null,"outcomes":["Analyze and examine traditional architectural techniques along with CAD (Computer-Aided Design) design process.","Create complex professional multi-media presentations as a means to communicate design intent."],"section_heading":"Architectural Technology, Certificate of Achievement (Academic Plan E021157D)","total_units":{"max":22,"min":22}}}'::jsonb, '{"arithmetic":"unequal","coverage":true,"invented":true,"listed":6,"placed":2}'::jsonb, '{"arithmetic":"unequal","confidence":{"catalog_year":100,"course_list_match":33,"ge_pattern":null,"source":80,"unit_arithmetic":30},"coverage":true,"gaps":["nested_award_not_read"],"invented":true,"listed":6,"placed":2}'::jsonb)),
c as (select count(*) filter (where r.checked is true) as n,
             coalesce(json_agg(v.i order by v.i) filter (where r.checked is true), '[]'::json) as keys
        from v join public.program_requirement_records r
          on r.college = v.college and r.control_number = v.control_number),
f as (select count(*) as n, coalesce(json_agg(v.i order by v.i), '[]'::json) as keys
        from v join public.program_requirement_records r
          on r.college = v.college and r.control_number = v.control_number
        join lateral (select pv.verdict, pv.requirements_fp from public.program_record_verdicts pv
                       where pv.college = v.college and pv.control_number = v.control_number
                       order by pv.id desc limit 1) lv on true
       where lv.verdict = 'confirm' and lv.requirements_fp = public.program_record_fp(r.record)),
e(expect) as (values (3)),
u as (
update public.program_requirement_records r
   set checks = v.after_checks
  from v
 where r.college = v.college and r.control_number = v.control_number
   and r.extracted_run = v.extracted_run and r.checks = v.before_checks and r.record = v.before_record
   and r.checked is not true
returning v.i),
s as (select count(*) as n, coalesce(json_agg(i order by i), '[]'::json) as keys from u)
select case when f.n > 0
            then ('s720e piles confirm guard: ' || f.n || ' rows hold a matching confirm verdict ' || f.keys::text)::int::text::json
            when s.n = e.expect - c.n
            then json_build_object('returned', s.n, 'keys', s.keys, 'skipped_checked', c.keys)
            else ('s720e piles guard: the UPDATE matched ' || s.n || ' rows, the plan names ' || (e.expect - c.n))::int::text::json end as returned
  from s, c, e, f;
